const isImportUpToDate = ({
  sourceModifiedAt,
  storedModifiedAt,
}: {
  sourceModifiedAt: string;
  storedModifiedAt: string;
}): boolean => {
  const storedTime = Date.parse(storedModifiedAt);
  return (
    !Number.isNaN(storedTime) && storedTime >= Date.parse(sourceModifiedAt)
  );
};

